#nullable enable

using Marten;
using Marten.Schema;
using StockFeed.Contracts;

namespace StockFeed.IntegrationTests;

/// <summary>
/// Fixed ids and fixed values, so a GIVEN can name things and a failing test is reproducible. The model declares
/// field names and types and never example values — this is where the values live, once.
///
/// IT SEEDS NOTHING, AND THE SCAFFOLD'S INSTRUCTION TO SEED THE FOREIGN EVENT IS WRONG HERE. It said: "append the
/// foreign events onto whatever streams the model says they land in… they are the world this system wakes up in."
/// For an ordinary imported event that is right. For a translation it is the opposite of right, twice over:
///
///   * StockNoticed is the trigger event. Seeding it into every test's world means every test starts with an
///     outstanding notice that the translator then translates — appending StockLevelSet into the very stream the
///     next assertion is about. Every GIVEN in the suite becomes a race with the automation.
///   * It would also make the landing mechanisms untestable. "A notice arrived and became our event" cannot be
///     asserted if a notice is already there before the test begins.
///
/// So the constants are here and the appending is each GIVEN's own job, which is what a GIVEN is for. Filed as a
/// finding against the scaffold's guidance rather than worked around silently.
/// </summary>
public sealed class SeedData : IInitialData
{
    public static readonly Guid ProductId = Guid.Parse("11111111-1111-1111-1111-111111111111");

    /// <summary>A second product, so a test can prove one stream's notices do not leak into another's.</summary>
    public static readonly Guid OtherProductId = Guid.Parse("22222222-2222-2222-2222-222222222222");

    /// <summary>The notice a GIVEN usually talks about.</summary>
    public static readonly Guid NoticeId = Guid.Parse("33333333-3333-3333-3333-333333333333");

    /// <summary>A second notice — a later one, or a stale one, depending on the sequence a test gives it.</summary>
    public static readonly Guid LaterNoticeId = Guid.Parse("44444444-4444-4444-4444-444444444444");

    /// <summary>One fixed instant, so a seeded timestamp is assertable.</summary>
    public static readonly DateTimeOffset SeededAt = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);

    /// <summary>What the warehouse says it has. Their word is "quantity".</summary>
    public const int Quantity = 5;

    /// <summary>A newer count, for the notice that supersedes.</summary>
    public const int LaterQuantity = 3;

    /// <summary>
    /// The sequence of the first notice. Not 1: a feed's sequence is the warehouse's counter, not ours, and
    /// starting at 7 keeps any test that accidentally assumes "sequence 1 means first" honest.
    /// </summary>
    public const long Sequence = 7;

    public const long LaterSequence = 8;

    /// <summary>Older than <see cref="Sequence"/> — the out-of-order arrival.</summary>
    public const long StaleSequence = 3;

    public static StockNoticed Noticed(
        Guid? noticeId = null, int? quantity = null, long? sequence = null, Guid? productId = null) =>
        new(productId ?? ProductId, noticeId ?? NoticeId, quantity ?? Quantity, sequence ?? Sequence, SeededAt);

    public static StockLevelSet LevelSet(
        Guid? noticeId = null, int? onHand = null, long? sequence = null, Guid? productId = null) =>
        new(productId ?? ProductId, noticeId ?? NoticeId, onHand ?? Quantity, sequence ?? Sequence, SeededAt);

    public Task Populate(IDocumentStore store, CancellationToken cancellation) => Task.CompletedTask;
}
